<?php
use Dompdf\Dompdf;use Dompdf\Options;
// Landscape, slide-style audit report built from structured AI output
final class Report{
  const SYSTEM=<<<'TXT'
You are a senior local-marketing consultant (Google Business Profile, local SEO, websites and conversion) with 15 years of experience. You are writing a premium, well-researched growth audit for a business owner on behalf of a digital marketing agency.

FOCUS
- This audit is about what is holding the business back. Lead with problems and missed opportunities, ordered by how much they cost the business in customers. Mention strengths only briefly.
- Every problem must be concrete: what exactly is wrong (with the numbers from the audit data), what it costs them (lost visibility, calls, trust or revenue) and the specific fix.
- Research their industry and city: how customers search for and choose this kind of business, demand, seasonality, what top competitors do differently, and current trends (e.g. AI search, reviews, WhatsApp, mobile). Use real, attributable statistics with publisher and year as "source". If you are not sure a figure is real, leave it out.
- Show what is realistically achievable with the right work, with conservative, clearly labelled estimates.
- Tone: expert, direct and respectful. No hype, no pressure, no begging for business. The agency appears only in "how_we_help" and "closing".
- Clear, simple English. Plain text only inside JSON strings: no HTML, no markdown, no emojis. Keep every text within the stated length.

OUTPUT: return ONLY one valid JSON object (no code fences, nothing before or after) with exactly these keys:
{
 "headline": "one sentence (max 140 chars): the most important thing holding them back",
 "summary": "2 short paragraphs separated by \n\n (max 650 chars total): where they lose customers today and what matters most",
 "strengths": ["2-3 short things they already do well (max 60 chars each)"],
 "market": {"search_term": "main search customers use", "monthly_searches": number, "insight": "max 330 chars: how customers in their city choose this kind of business", "stats": [{"value": "e.g. 76%", "label": "max 90 chars", "source": "publisher, year"}]},
 "industry_trends": [{"title": "max 45 chars", "detail": "max 170 chars: what is changing in their industry and what it means for them"}],
 "journey": {"monthly_searches": number, "profile_views": number, "actions": number, "customers": number, "note": "max 140 chars: these are estimates and how they were reached"},
 "competitors_insight": "max 330 chars: where the named competitors beat them, using the numbers",
 "findings": [{"area": "Google Maps|Reviews|Website|Speed|Content|Conversion|Trust|Social", "title": "max 55 chars", "found": "max 200 chars, with numbers", "why": "max 180 chars: what it costs them", "fix": "max 180 chars: the specific fix", "impact": "High|Medium|Low", "effort": "Low|Medium|High"}],
 "opportunity": {"customer_value": number, "current_enquiries_month": number, "potential_enquiries_month": number, "conversion_rate": number, "assumptions": "max 200 chars"},
 "outcomes": [{"metric": "max 40 chars", "today": "max 25 chars", "target": "max 25 chars", "timeframe": "max 15 chars"}],
 "plan": [{"phase": "Weeks 1-2", "title": "max 35 chars", "actions": ["2-3 actions, max 60 chars each"], "result": "max 80 chars"}],
 "quick_wins": [{"title": "max 45 chars", "how": "max 120 chars they can do themselves"}],
 "how_we_help": [{"service": "max 45 chars", "what": "max 130 chars, tied to the problems found", "result": "max 70 chars"}],
 "closing": "max 280 chars, warm, no pressure"
}
Provide 4 market stats, 3 industry trends, 6-9 findings ordered by impact (most costly first), 3-4 outcomes, 4 plan phases, 5 quick wins and 3 how_we_help items. Numbers must be plain numbers (no currency symbols or commas).
TXT;
  const PLACES=['cover'=>'Cover','summary'=>'At a glance','journey'=>'Market & customers','website'=>'Findings – website','maps'=>'Findings – Google Maps','competitors'=>'Competitors','growth'=>'Opportunity','plan'=>'Roadmap','tips'=>'Quick wins','why'=>'How we help','cta'=>'Closing page','any'=>'Any section'];
  const AREA=['Google Maps'=>['#EF4444','maps'],'Reviews'=>['#F59E0B','reviews'],'Website'=>['#3B82F6','website'],'Speed'=>['#8B5CF6','speed'],'Content'=>['#14B8A6','content'],'Conversion'=>['#EC4899','conversion'],'Trust'=>['#6366F1','trust'],'Social'=>['#0EA5E9','social']];
  static function competitors($lead){
    if(!$lead['campaign_id'])return [];
    return DB::all('SELECT name,rating,reviews,position,website FROM leads WHERE campaign_id=? AND id<>? ORDER BY position LIMIT 5',[$lead['campaign_id'],$lead['id']]);}
  static function prompt($type,$id=null){
    return $id?DB::row('SELECT * FROM prompts WHERE id=?',[$id]):DB::row('SELECT * FROM prompts WHERE type=? ORDER BY is_active DESC,id LIMIT 1',[$type]);}
  static function compact($audit){return je(array_map(fn($c)=>['area'=>$c['cat']??'','check'=>$c['label'],'status'=>$c['status'],'detail'=>$c['detail']],$audit['checks']??[]));}
  // Pull the JSON object out of an AI reply (tolerates code fences / stray text)
  static function parse($raw){
    $s=trim(preg_replace('~^```(?:json)?|```$~m','',$raw));
    $a=strpos($s,'{');$b=strrpos($s,'}');
    if($a===false||$b===false)return null;
    $d=json_decode(substr($s,$a,$b-$a+1),true);
    return is_array($d)&&!empty($d['summary'])?$d:null;}
  static function generate($leadId,$opt=[],$progress=null){
    $P=fn($p,$m)=>$progress?$progress($p,$m):null;
    $lead=DB::row('SELECT l.*,COALESCE(c.keyword,l.category) keyword FROM leads l LEFT JOIN campaigns c ON c.id=l.campaign_id WHERE l.id=?',[$leadId]);
    if(!$lead)throw new Exception('Lead not found');
    $P(60,'Preparing audit data for the AI');
    $a=jd($lead['audit']);
    $hasWeb=!empty($lead['website'])&&empty($a['website']['meta']['down']);
    $p=self::prompt($hasWeb?'report_website':'report_noweb',(int)($opt[$hasWeb?'pw':'pn']??0)?:null);
    if(!$p)throw new Exception('No report prompt found');
    $comp=self::competitors($lead);
    $cats=array_merge($a['website']['cats']??[],$a['map']['cats']??[]);
    $vars=lead_vars($lead,['web_score'=>$lead['web_score']??'N/A','map_score'=>$lead['map_score']??'N/A','web_categories'=>$cats?implode(', ',array_map(fn($k,$v)=>"$k $v/100",array_keys($cats),$cats)):'n/a','position'=>$lead['position']?:'n/a','website_audit'=>$hasWeb?self::compact($a['website']??[]):'No website','map_audit'=>self::compact($a['map']??[]),'competitors'=>$comp?je($comp):'none found','services'=>str_replace("\n",'; ',setting('services'))]);
    $P(65,'AI is researching & writing the report (usually 1–3 min)');
    $user=tpl($p['content'],$vars);
    $research=setting('ai_web_research','1')==='1';
    $raw=AI::complete(self::SYSTEM,$user,16000,null,['research'=>$research,'op'=>'report']);
    $d=self::parse($raw);
    if(!$d){$P(78,'Tidying the AI answer');$raw=AI::complete(self::SYSTEM,$user."\n\nIMPORTANT: your previous answer was not valid JSON. Reply with the JSON object only.",16000,null,['op'=>'report']);$d=self::parse($raw);}
    if(!$d)throw new Exception('The AI did not return a usable report. Please try again or use a different model.');
    $P(86,'Designing the PDF: charts, illustrations & layout');
    $tok=token(16);
    $full=self::render($lead,$a,$d,$hasWeb,$comp,$p['id']);
    $P(92,'Rendering PDF pages');
    $pdf=self::pdf($full);
    $P(97,'Saving report');
    $file='storage/reports/'.date('Ym').'/'.preg_replace('/[^a-z0-9]+/i','-',mb_substr($lead['name'],0,40)).'-'.$tok.'.pdf';
    @mkdir(dirname(ROOT.'/'.$file),0755,true);
    file_put_contents(ROOT.'/'.$file,$pdf);
    return DB::insert('reports',['lead_id'=>$leadId,'prompt_id'=>$p['id'],'token'=>$tok,'html'=>je($d),'pdf'=>$file]);}
  // Replace emojis / symbols the PDF fonts cannot draw (they show as "?")
  static function glyphs($s){
    $s=strtr((string)$s,['✔'=>'✓','✅'=>'✓','☑'=>'✓','✘'=>'×','✗'=>'×','❌'=>'×','➡'=>'→','👉'=>'→','⭐'=>'★','🌟'=>'★','“'=>'“','”'=>'”','‘'=>'‘','’'=>'’','—'=>'–']);
    $s=preg_replace_callback('/[\x{1F000}-\x{1FAFF}\x{2600}-\x{27BF}\x{2B00}-\x{2BFF}\x{FE00}-\x{FE0F}\x{200D}\x{20E3}]/u',fn($m)=>in_array($m[0],['✓','★','☆','×','→'],true)?$m[0]:'',$s);
    return trim(preg_replace('/[ \t]{2,}/',' ',$s));}
  static function t($s){return e(self::glyphs($s));}
  static function fonts(){
    $F=str_replace('\\','/',ROOT.'/app/fonts/');$o='';
    foreach([['Inter',400,'Inter-Regular'],['Inter',500,'Inter-Medium'],['Inter',600,'Inter-SemiBold'],['Inter',700,'Inter-Bold'],['InterTight',600,'InterTight-SemiBold'],['InterTight',700,'InterTight-Bold'],['InterTight',800,'InterTight-ExtraBold']] as [$f,$w,$n])$o.="@font-face{font-family:'$f';font-weight:$w;src:url('$F$n.ttf') format('truetype');}";
    foreach(array_unique([setting('font_heading'),setting('font_body')]) as $n){$f=STORAGE.'/fonts/'.preg_replace('/[^a-z0-9_-]/i','',$n).'.ttf';if($n&&is_file($f))$o.="@font-face{font-family:'$n';src:url('".str_replace('\\','/',$f)."') format('truetype');}";}
    return $o;}
  static function fileUri($f){
    if(!is_file($f))return '';
    $mime=mime_content_type($f)?:'image/png';
    if($mime==='image/webp'&&function_exists('imagecreatefromwebp')){$i=imagecreatefromwebp($f);imagesavealpha($i,true);ob_start();imagepng($i);return 'data:image/png;base64,'.base64_encode(ob_get_clean());}
    if($mime==='text/plain'||$mime==='image/svg')$mime='image/svg+xml';
    return 'data:'.$mime.';base64,'.base64_encode(file_get_contents($f));}
  static function logo(){return self::fileUri(ROOT.'/'.ltrim(setting('company_logo','assets/img/default-logo.png'),'/'));}
  // Uploaded doodle for a section (prompt-specific first), otherwise the built-in illustration
  static function art($key,$pid,$P,$A){
    static $any=null;
    $r=DB::row('SELECT file FROM assets WHERE placement=? AND (prompt_id=? OR prompt_id IS NULL) ORDER BY prompt_id IS NULL,RAND() LIMIT 1',[$key,$pid]);
    if(!$r&&$key!=='cover'){$any??=DB::all('SELECT file FROM assets WHERE placement=\'any\' AND (prompt_id=? OR prompt_id IS NULL)',[$pid]);if($any)$r=$any[array_rand($any)];}
    if($r&&($u=self::fileUri(ROOT.'/'.$r['file'])))return $u;
    return Illus::uri(Illus::get($key,$P,$A));}
  // Landscape A4 = 1123 × 794 px. Every page has a fixed content budget (texts are clipped) so nothing spills onto blank pages.
  static function render($lead,$a,$d,$hasWeb,$comp,$pid=0){
    $S=fn($k,$x='')=>setting($k,$x);$n=fn($v)=>(float)preg_replace('/[^\d.]/','',(string)$v);
    $t=fn($s,$max=0)=>e($max?mb_strimwidth(self::glyphs($s),0,$max,'…'):self::glyphs($s));
    $P=$S('brand_primary','#0B0B0B');$A=$S('brand_accent','#B8860B');
    $std=['','Inter','DejaVu Sans','Helvetica','Times-Roman','Courier'];
    $fh=in_array($S('font_heading'),$std,true)?'InterTight':$S('font_heading');$fb=in_array($S('font_body'),$std,true)?'Inter':$S('font_body');
    $Pl=Illus::tint($P,.94);$Al=Illus::tint($A,.86);$Am=Illus::tint($A,.5);
    $cur=$S('currency_symbol','₹');$money=fn($v)=>$cur.number_format((float)$v);
    $ws=$hasWeb&&$lead['web_score']!==null?(int)$lead['web_score']:null;$ms=$lead['map_score']!==null?(int)$lead['map_score']:null;
    $low=fn($v)=>$v!==null&&$v<80; // scores are shown only when they need work
    $checks=array_merge(array_map(fn($c)=>$c+['src'=>'Google Maps'],$a['map']['checks']??[]),$hasWeb?array_map(fn($c)=>$c+['src'=>'Website'],$a['website']['checks']??[]):[]);
    $cnt=['pass'=>0,'warn'=>0,'fail'=>0];foreach($checks as $c)$cnt[$c['status']]=($cnt[$c['status']]??0)+1;
    $mm=$a['map']['meta']??[];
    $F=array_values(array_filter((array)($d['findings']??[]),fn($x)=>!empty($x['title'])));
    usort($F,fn($x,$y)=>(['high'=>0,'medium'=>1,'low'=>2][strtolower($x['impact']??'')]??3)<=>(['high'=>0,'medium'=>1,'low'=>2][strtolower($y['impact']??'')]??3));
    $high=count(array_filter($F,fn($x)=>strtolower($x['impact']??'')==='high'));
    $op=$d['opportunity']??[];$cv=$n($op['customer_value']??0);$ce=$n($op['current_enquiries_month']??0);$pe=$n($op['potential_enquiries_month']??0);$cr=$n($op['conversion_rate']??0);if($cr>1)$cr/=100;if($cr<=0)$cr=.2;
    $missed=max(0,(int)round($pe-$ce));$rev=round($missed*12*$cr*$cv);
    $css=self::fonts()."@page{size:A4 landscape;margin:0}*{box-sizing:border-box}body{margin:0;font-family:'$fb',Inter,sans-serif;color:#1E293B;font-size:10pt;line-height:1.5}h1,h2,h3{font-family:'$fh',InterTight,sans-serif;margin:0;color:#0F172A}p{margin:0 0 7px}table{border-collapse:collapse}td{vertical-align:top}"
      .".pg{padding:34px 46px 0;page-break-before:always}.pg.first{page-break-before:auto}.pg.full{padding:0}"
      .".kick{display:inline-block;font-size:7.5pt;letter-spacing:2px;text-transform:uppercase;font-weight:700;color:#fff;background:$P;border-radius:20px;padding:4px 12px}.pt{font-family:'$fh',InterTight;font-size:22pt;font-weight:800;color:#0F172A;line-height:1.15;margin-top:10px}.ps{color:#64748B;font-size:10pt;margin-top:5px}.rule{height:4px;width:64px;background:$A;border-radius:2px;margin:12px 0 18px}"
      .".card{background:#fff;border:1px solid #E5E9F2;border-radius:14px;padding:16px 18px}.soft{background:$Pl;border-color:$Pl}.lbl{font-size:7.5pt;letter-spacing:1.3px;text-transform:uppercase;color:#64748B;font-weight:700;margin-bottom:6px}.big{font-family:'$fh',InterTight;font-size:24pt;font-weight:800;line-height:1.05;color:#0F172A}.sm{font-size:8.5pt;color:#64748B}.chip{display:inline-block;padding:2px 9px;border-radius:10px;font-size:7.5pt;font-weight:700}"
      .".w{width:100%}.fx{table-layout:fixed}.tbl{width:100%}.tbl th{text-align:left;font-size:7.5pt;letter-spacing:1px;text-transform:uppercase;color:#64748B;padding:7px 8px;border-bottom:2px solid #E5E9F2}.tbl td{padding:7px 8px;border-bottom:1px solid #EEF1F6;font-size:9.3pt}.me td{background:$Al;font-weight:700}"
      .".hl{background:$Al;border-left:5px solid $A;border-radius:10px;padding:13px 16px;font-size:11.5pt;color:#0F172A;font-weight:600;line-height:1.4}.num{display:inline-block;width:26px;height:26px;border-radius:13px;color:#fff;text-align:center;font-weight:700;font-size:10pt;line-height:1;padding-top:6px}";
    $head=fn($kick,$title,$sub='')=>'<span class="kick">'.$t($kick).'</span><div class="pt">'.$t($title,90).'</div>'.($sub?'<div class="ps">'.$t($sub,170).'</div>':'').'<div class="rule"></div>';
    $page=fn($body,$cls='')=>'<div class="pg '.$cls.'">'.$body.'</div>';
    $tile=fn($label,$val,$sub='',$c='#0F172A',$bg='#fff')=>'<div class="card" style="background:'.$bg.'"><div class="lbl">'.e($label).'</div><div class="big" style="color:'.$c.'">'.$val.'</div>'.($sub?'<div class="sm" style="margin-top:4px">'.$sub.'</div>':'').'</div>';
    $areaIc=fn($ar)=>self::AREA[$ar]??['#64748B','content'];
    $impC=fn($i)=>['high'=>['#FEE2E2','#B91C1C'],'medium'=>['#FEF3C7','#B45309'],'low'=>['#DCFCE7','#15803D']][strtolower((string)$i)]??['#F1F5F9','#475569'];
    $logo=self::logo();$o='';
    // 1 · Cover – problems first, scores only when below 80
    $stat=fn($v,$l,$c)=>'<tr><td style="padding:0 0 14px"><table class="w"><tr><td style="width:64px"><div style="width:52px;height:52px;border-radius:14px;background:'.$c.';color:#fff;text-align:center;font-family:'.$fh.',InterTight;font-weight:800;font-size:18pt;line-height:1;padding-top:13px">'.$v.'</div></td><td style="vertical-align:middle;font-size:11pt;color:#0F172A;font-weight:600">'.$l.'</td></tr></table></td></tr>';
    $sc='';foreach([['Website',$ws],['Google Maps',$ms]] as [$lb,$v])if($low($v))$sc.='<td style="padding:0 8px;text-align:center"><img src="'.Charts::gauge($v,'',120).'" style="width:70px"><div class="sm" style="font-weight:600;color:#334155">'.$lb.'</div></td>';
    $o.='<div class="pg first full"><table class="w"><tr><td style="width:57%;height:688px;background:'.$P.';padding:54px 54px 40px;vertical-align:top">'.($logo?'<img src="'.$logo.'" style="height:70px">':'<div style="color:#fff;font-size:20pt;font-weight:800">'.e($S('company_name')).'</div>').'<div style="margin-top:70px"><span class="kick" style="background:'.$A.'">Growth audit · '.date('F Y').'</span></div><div style="font-family:'.$fh.',InterTight;font-size:38pt;font-weight:800;color:#fff;line-height:1.05;margin-top:16px">'.$t($lead['name'],60).'</div><div style="color:'.$Am.';font-size:14pt;margin-top:12px;font-weight:600">'.($hasWeb?'Website & Google Maps audit':'Google Maps audit & website plan').'</div><div style="color:#CBD5E1;font-size:9.5pt;margin-top:20px;line-height:1.75">'.$t(implode(' · ',array_filter([$lead['category'],$lead['city']])),80).'<br>'.$t($lead['address'],90).($lead['website']?'<br>'.$t(preg_replace('~^https?://|/$~','',$lead['website']),60):'').'</div><table style="margin-top:34px"><tr>'.implode('',array_map(fn($x)=>'<td style="padding-right:16px"><div style="font-size:7.5pt;letter-spacing:1.3px;text-transform:uppercase;color:'.$Am.';font-weight:700">'.$x[0].'</div><div style="color:#fff;font-size:9.5pt;margin-top:2px">'.$x[1].'</div></td>',[['01','Summary'],['02','Problem map'],['03','Market research'],['04','Findings & fixes'],['05','90-day plan']])).'</tr></table><div style="margin-top:46px;border-top:1px solid #333;padding-top:14px;color:#CBD5E1;font-size:8.5pt">Prepared by <b style="color:#fff">'.e($S('company_name')).'</b> · '.e($S('company_phone')).' · '.e(preg_replace('~^https?://|/$~','',$S('company_website'))).'</div></td><td style="background:'.$Pl.';padding:60px 44px 34px;height:688px;vertical-align:top"><div class="lbl" style="color:'.$P.'">At a glance</div><div style="font-family:'.$fh.',InterTight;font-size:17pt;font-weight:800;color:#0F172A;line-height:1.25;margin:6px 0 26px">'.$t($d['headline']??'',140).'</div><table class="w">'.$stat(count($F),'problems holding you back','#EF4444').$stat($high,'with a high impact on enquiries','#F97316').$stat(count((array)($d['quick_wins']??[])),'quick wins you can do this week','#10B981').($missed?$stat($missed,'extra enquiries a month are realistic','#6366F1'):'').'</table>'.($sc?'<div class="lbl" style="margin-top:6px">Scores that need work</div><table><tr>'.$sc.'</tr></table>':'').'</td></tr></table></div>';
    // 2 · Executive summary
    $sum='';foreach(array_slice(array_filter(explode("\n\n",(string)($d['summary']??''))),0,2) as $p)$sum.='<p style="font-size:10.8pt;color:#334155;line-height:1.6">'.$t($p,380).'</p>';
    $top='';foreach(array_slice($F,0,3) as $i=>$x){[$c,$g]=$areaIc($x['area']??'');$top.='<tr><td style="padding-bottom:10px"><div class="card" style="border-left:5px solid '.$c.';padding:12px 16px"><table class="w"><tr><td style="width:40px"><span class="num" style="background:'.$c.'">'.($i+1).'</span></td><td><b style="font-family:'.$fh.',InterTight;font-size:11.5pt;color:#0F172A">'.$t($x['title'],60).'</b><div style="font-size:9pt;color:#475569;margin-top:2px">'.$t($x['why']??'',150).'</div></td></tr></table></div></td></tr>';}
    $str='';foreach(array_slice((array)($d['strengths']??[]),0,3) as $s)$str.='<td style="padding-right:8px"><table><tr><td style="width:22px"><img src="'.Charts::icon('pass',18).'" style="width:15px"></td><td style="font-size:8.8pt;color:#334155">'.$t($s,60).'</td></tr></table></td>';
    $o.=$page($head('Executive summary','What is holding '.$lead['name'].' back').'<table class="w"><tr><td style="width:48%;padding-right:22px">'.$sum.($missed&&$rev?'<table class="w" style="margin-top:10px"><tr><td style="width:50%;padding-right:8px">'.$tile('Missed enquiries','~'.$missed.' / mo','realistic gap today','#DC2626','#FEF2F2').'</td><td style="padding-left:8px">'.$tile('Revenue at stake',$money($rev),'per year (estimate)','#0F172A',$Al).'</td></tr></table>':'').($str?'<div class="lbl" style="margin-top:16px;color:#059669">Already working</div><table><tr>'.$str.'</tr></table>':'').'</td><td><div class="lbl" style="color:#DC2626">The 3 problems costing you most</div><table class="w">'.$top.'</table></td></tr></table>');
    // 3 · Problem map – where the issues are (scores only for areas below 80)
    $areas=[];foreach($checks as $c){$k=$c['cat']??$c['src'];$areas[$k]??=[$k,0,0];if($c['status']==='fail')$areas[$k][1]++;elseif($c['status']==='warn')$areas[$k][2]++;}
    $areas=array_values(array_filter($areas,fn($r)=>$r[1]+$r[2]>0));usort($areas,fn($x,$y)=>($y[1]*2+$y[2])<=>($x[1]*2+$x[2]));$areas=array_slice($areas,0,9);
    $cats=array_filter(array_merge($hasWeb?($a['website']['cats']??[]):[],$a['map']['cats']??[]),fn($v)=>$v<80);asort($cats);$cats=array_slice($cats,0,8,true);
